// Why Code: validates one reservation request against the business rules (opening hours, slot grid,
// capacity overlap, ownership, cancel cutoff) and decides at most ONE write. Native nodes would need
// ~15 IF/Set nodes and still cannot compute peak overlap per slot.
const TZ = 'Asia/Jakarta';
const input = $('When called by CS agent').first().json;
const s = $('Load Settings').first().json || {};
const services = $('Load Services').all().map(i => i.json).filter(r => r.name && r.active !== false);
const reservations = $('Load Reservations').all().map(i => i.json).filter(r => r.bookingCode);

const action = String(input.action ?? '').trim().toLowerCase();
const reply = (ok, message, data = {}, write = { op: 'none' }) => [{ json: { ok, action, message, data, write } }];
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ---- config (from Automation Settings; never hard-coded) ----
const need = ['csOpenTime', 'csCloseTime', 'csSlotMinutes', 'csSlotCapacity', 'csCancelCutoffHours', 'csMaxDaysAhead'];
const missing = need.filter(k => s[k] === null || s[k] === undefined || s[k] === '');
if (missing.length) {
  return reply(false, `Sistem reservasi belum dikonfigurasi (${missing.join(', ')}). Minta maaf ke customer dan tawarkan eskalasi ke admin.`);
}
const toMin = (t) => { const m = String(t).trim().match(/^(\d{1,2})[:.](\d{2})$/); return m ? Number(m[1]) * 60 + Number(m[2]) : NaN; };
const openMin = toMin(s.csOpenTime);
const closeMin = toMin(s.csCloseTime);
const slot = Number(s.csSlotMinutes);
const cap = Number(s.csSlotCapacity);
const cutoffH = Number(s.csCancelCutoffHours);
const maxDays = Number(s.csMaxDaysAhead);
const closedDays = String(s.csClosedWeekdays ?? '').split(/[\s,]+/).filter(Boolean).map(Number); // 1=Senin .. 7=Minggu
if ([openMin, closeMin, slot, cap, cutoffH, maxDays].some(n => !Number.isFinite(n)) || slot <= 0 || cap <= 0) {
  return reply(false, 'Konfigurasi reservasi tidak valid. Minta maaf ke customer dan tawarkan eskalasi ke admin.');
}

// ---- helpers ----
const now = DateTime.now().setZone(TZ);
const parseLocal = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const d = v instanceof Date ? DateTime.fromJSDate(v) : DateTime.fromISO(String(v).trim(), { zone: TZ });
  return d.isValid ? d.setZone(TZ).startOf('minute') : null;
};
const fmt = (d) => d.setLocale('id').toFormat("cccc, d LLLL yyyy 'pukul' HH:mm 'WIB'");
const local = (d) => d.toFormat("yyyy-MM-dd'T'HH:mm");
const serviceNames = services.map(x => x.name);
const findService = (name) => {
  const n = String(name ?? '').trim().toLowerCase();
  return n ? services.find(x => x.name.toLowerCase() === n) || null : null;
};
const confirmed = reservations
  .filter(r => r.status === 'confirmed')
  .map(r => ({ ...r, start: parseLocal(r.startAt), end: parseLocal(r.endAt) }))
  .filter(r => r.start && r.end);

const slotProblem = (svc, start, excludeCode) => {
  const dur = Number(svc.durationMinutes);
  const end = start.plus({ minutes: dur });
  if (start <= now) return 'waktu tersebut sudah lewat';
  if (start > now.plus({ days: maxDays })) return `reservasi hanya bisa maksimal ${maxDays} hari ke depan`;
  if (closedDays.includes(start.weekday)) return `kami tutup setiap hari ${start.setLocale('id').toFormat('cccc')}`;
  const sm = start.hour * 60 + start.minute;
  if (sm < openMin || sm + dur > closeMin) return `di luar jam operasional ${s.csOpenTime}-${s.csCloseTime} (layanan ${svc.name} butuh ${dur} menit)`;
  if ((sm - openMin) % slot !== 0) return `jam mulai harus kelipatan ${slot} menit dari ${s.csOpenTime}`;
  const overlapping = confirmed.filter(r => r.bookingCode !== excludeCode && r.start < end && r.end > start);
  const points = [start, ...overlapping.map(r => r.start).filter(p => p > start && p < end)];
  const peak = Math.max(0, ...points.map(p => overlapping.filter(r => r.start <= p && r.end > p).length));
  if (peak >= cap) return 'slot tersebut sudah penuh';
  return null;
};
const availableTimes = (svc, day, excludeCode) => {
  const out = [];
  const base = day.startOf('day');
  for (let m = openMin; m + Number(svc.durationMinutes) <= closeMin; m += slot) {
    const t = base.plus({ minutes: m });
    if (!slotProblem(svc, t, excludeCode)) out.push(t.toFormat('HH:mm'));
  }
  return out;
};
const publicRow = (r) => {
  const st = parseLocal(r.startAt);
  return { bookingCode: r.bookingCode, serviceName: r.serviceName, startAt: st ? local(st) : null, when: st ? fmt(st) : null, status: r.status, customerName: r.customerName };
};
const ownBooking = (code) => {
  const c = String(code ?? '').trim().toUpperCase();
  return reservations.find(r => r.bookingCode === c && String(r.customerId) === customerId && r.status === 'confirmed') || null;
};
const cutoffProblem = (b) => {
  const st = parseLocal(b.startAt);
  if (st && st.diff(now, 'hours').hours < cutoffH) return `perubahan/pembatalan hanya bisa paling lambat ${cutoffH} jam sebelum jadwal; arahkan customer ke admin`;
  return null;
};
const adminText = (title, b, extra = '') =>
  `<b>${esc(title)}</b>\nKode: <code>${esc(b.bookingCode)}</code>\nCustomer: ${esc(b.customerName)}${b.customerPhone ? ' (' + esc(b.customerPhone) + ')' : ''}\nLayanan: ${esc(b.serviceName)}\nJadwal: ${esc(fmt(parseLocal(b.startAt)))}${extra}`;

// ---- identity: always from the trigger mapping, never from the model ----
const customerId = String(input.customerId ?? '').trim();
if (!customerId) return reply(false, 'Identitas customer tidak tersedia; reservasi tidak bisa diproses.');

// ---- actions ----
if (action === 'list') {
  const mine = reservations
    .filter(r => String(r.customerId) === customerId && r.status === 'confirmed')
    .filter(r => { const e = parseLocal(r.endAt); return e && e > now; })
    .sort((a, b) => parseLocal(a.startAt) - parseLocal(b.startAt))
    .map(publicRow);
  return reply(true, mine.length ? `Customer punya ${mine.length} reservasi aktif.` : 'Customer tidak punya reservasi aktif.', { reservations: mine });
}

if (action === 'cancel') {
  const b = ownBooking(input.bookingCode);
  if (!b) return reply(false, 'Kode booking tidak ditemukan di reservasi aktif milik customer ini.');
  const cp = cutoffProblem(b);
  if (cp) return reply(false, `Pembatalan ditolak: ${cp}.`, { reservation: publicRow(b) });
  const row = { bookingCode: b.bookingCode, customerId, serviceName: b.serviceName, startAt: b.startAt, endAt: b.endAt, status: 'cancelled' };
  return reply(true, `Reservasi ${b.bookingCode} berhasil dibatalkan.`, { reservation: { ...publicRow(b), status: 'cancelled' } },
    { op: 'update', row, adminText: adminText('❌ Reservasi dibatalkan', b) });
}

const svcRequested = findService(input.serviceName);
if (input.serviceName && !svcRequested) {
  return reply(false, `Layanan "${input.serviceName}" tidak tersedia.`, { services: serviceNames });
}

if (action === 'check') {
  if (!svcRequested) return reply(false, 'Sebutkan layanan yang ingin dicek.', { services: serviceNames });
  const raw = String(input.startAt ?? '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
    const day = parseLocal(raw);
    if (!day) return reply(false, 'Format tanggal tidak valid. Gunakan YYYY-MM-DD.');
    const times = availableTimes(svcRequested, day);
    return reply(true, times.length ? `Ada ${times.length} jam mulai tersedia.` : 'Tidak ada slot kosong pada tanggal tersebut.',
      { service: svcRequested.name, date: raw, availableTimes: times });
  }
  const start = parseLocal(raw);
  if (!start) return reply(false, 'Format waktu tidak valid. Gunakan YYYY-MM-DD atau YYYY-MM-DDTHH:mm (WIB).');
  const p = slotProblem(svcRequested, start);
  return reply(true, p ? `Slot tidak tersedia: ${p}.` : `Slot ${fmt(start)} tersedia.`,
    { service: svcRequested.name, startAt: local(start), available: !p, reason: p, alternativeTimes: p ? availableTimes(svcRequested, start).slice(0, 8) : [] });
}

if (action === 'create') {
  if (!svcRequested) return reply(false, 'Layanan wajib diisi.', { services: serviceNames });
  const start = parseLocal(input.startAt);
  if (!start || !String(input.startAt).includes('T')) return reply(false, 'Tanggal dan jam wajib diisi (YYYY-MM-DDTHH:mm, WIB).');
  const name = String(input.customerName ?? '').trim();
  if (!name) return reply(false, 'Nama customer wajib diisi.');
  const dup = confirmed.find(r => String(r.customerId) === customerId && r.serviceName === svcRequested.name && +r.start === +start);
  if (dup) return reply(true, `Reservasi ini sudah tercatat dengan kode ${dup.bookingCode}.`, { reservation: publicRow(dup) });
  const p = slotProblem(svcRequested, start);
  if (p) return reply(false, `Reservasi gagal: ${p}.`, { alternativeTimes: availableTimes(svcRequested, start).slice(0, 8) });
  const ALPH = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let code;
  do { code = 'RSV-' + Array.from({ length: 6 }, () => ALPH[Math.floor(Math.random() * ALPH.length)]).join(''); }
  while (reservations.some(r => r.bookingCode === code));
  const row = {
    bookingCode: code, customerId, customerName: name, customerPhone: String(input.customerPhone ?? '').trim(),
    serviceName: svcRequested.name, startAt: start.toISO(), endAt: start.plus({ minutes: Number(svcRequested.durationMinutes) }).toISO(),
    status: 'confirmed', notes: String(input.notes ?? '').trim(), channel: String(input.channel ?? '').trim(),
  };
  return reply(true, `Reservasi berhasil dibuat dengan kode ${code}.`, { reservation: publicRow(row) },
    { op: 'insert', row, adminText: adminText('✅ Reservasi baru', row) });
}

if (action === 'reschedule') {
  const b = ownBooking(input.bookingCode);
  if (!b) return reply(false, 'Kode booking tidak ditemukan di reservasi aktif milik customer ini.');
  const cp = cutoffProblem(b);
  if (cp) return reply(false, `Perubahan ditolak: ${cp}.`, { reservation: publicRow(b) });
  const svc = svcRequested || findService(b.serviceName);
  if (!svc) return reply(false, 'Layanan pada reservasi ini sudah tidak tersedia; arahkan ke admin.');
  const start = parseLocal(input.startAt);
  if (!start || !String(input.startAt).includes('T')) return reply(false, 'Tanggal dan jam baru wajib diisi (YYYY-MM-DDTHH:mm, WIB).');
  const p = slotProblem(svc, start, b.bookingCode);
  if (p) return reply(false, `Perubahan gagal: ${p}.`, { alternativeTimes: availableTimes(svc, start, b.bookingCode).slice(0, 8) });
  const row = { bookingCode: b.bookingCode, customerId, serviceName: svc.name, startAt: start.toISO(), endAt: start.plus({ minutes: Number(svc.durationMinutes) }).toISO(), status: 'confirmed' };
  const updated = { ...b, ...row };
  return reply(true, `Reservasi ${b.bookingCode} dipindah ke ${fmt(start)}.`, { reservation: publicRow(updated) },
    { op: 'update', row, adminText: adminText('🔁 Reservasi diubah', updated, `\nSebelumnya: ${esc(fmt(parseLocal(b.startAt)))}`) });
}

return reply(false, `Aksi tidak dikenal: "${action}".`);
